import { ActionDefinition } from '../../../Action'
import { TableNameColumn, BooleanColumn, DocumentIdColumn, TemplateValueColumn } from '../../../../db'

export const createTask = ActionDefinition({
    $id: '2b3a6335531003003bf1d9109ec58759',
    name: 'Create Task',
    description:
        "Creates a task on any ServiceNow task table. After you choose the task table, you can dynamically select the fields to configure the action. A Parent field associates to a Parent record (Incident Task to Incident record).  To block the flow until this task is completed, select 'Wait'.",
    inputs: {
        task_table: TableNameColumn({
            label: 'Table',
            mandatory: true,
        }),
        wait: BooleanColumn({
            label: 'Wait',
        }),
        field_values: TemplateValueColumn({
            label: 'Field Values',
            maxLength: 65000,
            dependent: 'task_table',
        }),
    },
    outputs: {
        Table: TableNameColumn({
            label: 'Table',
        }),
        Record: DocumentIdColumn({
            label: 'Record',
            dependent: 'task_table',
            tableReference: true,
        }),
    },
})
